# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ELEKTROLİTİK HÜCRE YAPISI VE GALVANİK PİL İLE KARŞILAŞTIRMASI</text>\n  <rect x="25" y="45" width="320" height="195" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="185" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">Elektrolitik Hücrede İyon Göçü</text>\n  <rect x="125" y="82" width="120" height="28" rx="5" fill="#1e293b"/>\n  <text x="185" y="100" text-anchor="middle" font-size="11" font-weight="bold" fill="#ffffff">+   Üreteç (DC)   -</text>\n  <!-- Anot ve Katot Cubuklari -->\n  <rect x="65" y="125" width="95" height="95" rx="6" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="112" y="146" text-anchor="middle" font-size="12" font-weight="bold" fill="#991b1b">ANOT (+)</text>\n  <text x="112" y="166" text-anchor="middle" font-size="11" fill="#7f1d1d">Yükseltgenme</text>\n  <text x="112" y="184" text-anchor="middle" font-size="11" font-weight="bold" fill="#b91c1c">Anyonlar (-)</text>\n  <text x="112" y="202" text-anchor="middle" font-size="10" fill="#7f1d1d">anoda göç eder.</text>\n\n  <rect x="210" y="125" width="95" height="95" rx="6" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="257" y="146" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">KATOT (-)</text>\n  <text x="257" y="166" text-anchor="middle" font-size="11" fill="#14532d">İndirgenme</text>\n  <text x="257" y="184" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Katyonlar (+)</text>\n  <text x="257" y="202" text-anchor="middle" font-size="10" fill="#14532d">katoda göç eder.</text>\n\n  <rect x="365" y="45" width="310" height="195" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">Temel Özellikler</text>\n  <text x="380" y="95" font-size="12" fill="#78350f">• <tspan font-weight="bold">Enerji Dönüşümü:</tspan> Elektrik → Kimyasal</text>\n  <text x="380" y="120" font-size="12" fill="#78350f">• <tspan font-weight="bold">İstemlilik:</tspan> İstemsizdir (E°_hücre &lt; 0)</text>\n  <text x="380" y="145" font-size="12" fill="#78350f">• <tspan font-weight="bold">Uygulanan Gerilim:</tspan> Üreteç potansiyeli,</text>\n  <text x="390" y="163" font-size="11" fill="#78350f">|E°_pil| değerinden büyük olmalıdır.</text>\n  <text x="380" y="188" font-size="12" fill="#78350f">• <tspan font-weight="bold">Kutup İşaretleri:</tspan> Anot (+), Katot (-)</text>\n  <text x="380" y="213" font-size="11" font-weight="bold" fill="#b45309">(Galvanik pilde ise Anot (-), Katot (+) idi.)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">FARADAY ELEKTROLİZ BAĞINTILARI VE NİCEL HESAPLAMALAR</text>\n  <rect x="25" y="48" width="205" height="190" rx="10" fill="#e0e7ff" stroke="#4f46e5" stroke-width="2"/>\n  <text x="127" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#3730a3">1. Elektrik Yükü (Q)</text>\n  <rect x="42" y="88" width="170" height="40" rx="6" fill="#ffffff" stroke="#818cf8" stroke-width="1.5"/>\n  <text x="127" y="113" text-anchor="middle" font-size="14" font-weight="bold" fill="#312e81">Q = I · t</text>\n  <text x="38" y="150" font-size="11" fill="#312e81">• <tspan font-weight="bold">Q:</tspan> Elektrik yükü (Coulomb, C)</text>\n  <text x="38" y="172" font-size="11" fill="#312e81">• <tspan font-weight="bold">I:</tspan> Akım şiddeti (Amper, A)</text>\n  <text x="38" y="194" font-size="11" fill="#312e81">• <tspan font-weight="bold">t:</tspan> Zaman (<tspan font-weight="bold">saniye, s</tspan>)</text>\n  <text x="38" y="216" font-size="10" fill="#4f46e5">Not: Dakika verilirse 60 ile çarpılır!</text>\n\n  <rect x="247" y="48" width="205" height="190" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="349" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">2. Faraday Sabiti (1 F)</text>\n  <rect x="262" y="88" width="175" height="40" rx="6" fill="#ffffff" stroke="#4ade80" stroke-width="1.5"/>\n  <text x="349" y="113" text-anchor="middle" font-size="13" font-weight="bold" fill="#14532d">1 F = 1 mol e⁻ = 96500 C</text>\n  <text x="260" y="150" font-size="11" fill="#14532d">• Devreden geçen e⁻ molü:</text>\n  <text x="268" y="170" font-size="12" font-weight="bold" fill="#15803d">n(e⁻) = (I · t) / 96500</text>\n  <text x="260" y="196" font-size="11" fill="#14532d">• 1 F yük geçtiğinde 1 eşdeğer</text>\n  <text x="268" y="214" font-size="11" fill="#14532d">gram (M_A / z) madde toplanır.</text>\n\n  <rect x="470" y="48" width="205" height="190" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="572" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">3. Kütle Formülü (m)</text>\n  <rect x="485" y="88" width="175" height="40" rx="6" fill="#ffffff" stroke="#c084fc" stroke-width="1.5"/>\n  <text x="572" y="113" text-anchor="middle" font-size="12" font-weight="bold" fill="#581c87">m = (I · t · M_A) / (96500 · z)</text>\n  <text x="483" y="150" font-size="11" fill="#581c87">• <tspan font-weight="bold">m:</tspan> Toplanan kütle (gram)</text>\n  <text x="483" y="172" font-size="11" fill="#581c87">• <tspan font-weight="bold">M_A:</tspan> Atom/mol kütlesi (g/mol)</text>\n  <text x="483" y="194" font-size="11" fill="#581c87">• <tspan font-weight="bold">z:</tspan> İyon yükü / alınan-verilen</text>\n  <text x="491" y="212" font-size="11" fill="#581c87">elektron sayısı (tesir değerliği)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">SERİ BAĞLI ELEKTROLİZ KAPLARI VE ELEKTROLİTİK KAPLAMA</text>\n  <rect x="25" y="45" width="320" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="185" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">Seri Bağlı Elektroliz Kapları</text>\n  <text x="40" y="95" font-size="12" fill="#1e3a8a">• Tüm kaplardan geçen <tspan font-weight="bold">Q ve n(e⁻) eşittir.</tspan></text>\n  <rect x="45" y="110" width="280" height="45" rx="6" fill="#ffffff" stroke="#60a5fa" stroke-width="1.5"/>\n  <text x="185" y="137" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">n₁ · z₁ = n₂ · z₂ = n(e⁻)</text>\n  <text x="40" y="178" font-size="11" fill="#1e3a8a">• İyon yükü (z) küçük olan metalin katotta</text>\n  <text x="50" y="196" font-size="11" font-weight="bold" fill="#1e40af">toplanan mol sayısı daha büyüktür.</text>\n  <text x="40" y="218" font-size="11" fill="#1e3a8a">• Örnek: 1 mol e⁻ → 1 mol Na⁺, 1/2 mol Mg²⁺, 1/3 mol Al³⁺</text>\n\n  <rect x="365" y="45" width="310" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">Metal Kaplama (Örn: Gümüş Kaplama)</text>\n  <text x="380" y="95" font-size="12" fill="#14532d">• <tspan font-weight="bold">ANOT (+):</tspan> Kaplayacak saf metal (Ag çubuk)</text>\n  <text x="390" y="113" font-size="11" fill="#15803d">Ag(k) → Ag⁺(suda) + e⁻ (Anot aşınır)</text>\n  <text x="380" y="140" font-size="12" fill="#14532d">• <tspan font-weight="bold">KATOT (-):</tspan> Kaplanacak eşya (Demir kaşık)</text>\n  <text x="390" y="158" font-size="11" fill="#15803d">Ag⁺(suda) + e⁻ → Ag(k) (Kaşık kaplanır)</text>\n  <text x="380" y="185" font-size="12" fill="#14532d">• <tspan font-weight="bold">Çözelti:</tspan> Ag⁺ iyonu içeren elektrolit (AgNO₃)</text>\n  <text x="380" y="212" font-size="11" font-weight="bold" fill="#166534">Çözeltideki Ag⁺ derişimi işlem boyunca sabit kalır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
